	if((item = malloc(sizeof(*item))) == NULL)
		return ERROR;
	item->next = *list;
	item->object_ptr = object_ptr;
	*list = item;
	return OK;
	}

servicesmember *add_child_link_to_service(service *svc, service *child_ptr) { /* <=== add_child_link_to_service */ 
	servicesmember *new_servicesmember = NULL;

	/* make sure we have the data we need */
	if(svc == NULL || child_ptr == NULL)
		return NULL;

	/* allocate memory */
	if((new_servicesmember = (servicesmember *)malloc(sizeof(servicesmember))) 
